import java.io.*;
import java.util.*;

public class B {
    public static void main(String[] args) throws IOException {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        while (in.hasNext()) {
            int n = in.nextInt();
            String s = in.next();
            boolean paren = false;
            boolean start = true;
            int maxOut = 0;
            int curOut = 0;
            int inWords = 0;
            int i = 0;
            while (i < n) {
                char c = s.charAt(i++);
                switch (c) {
                    case '(':
                        paren = true;
                        start = true;
                        curOut = 0;
                        break;
                    case ')':
                        paren = false;
                        curOut = 0;
                        break;
                    case '_':
                        if (paren) {
                            start = true;
                        } else {
                            curOut = 0;
                        }
                        break;
                    default:
                        if (paren) {
                            if (start) {
                                inWords++;
                                start = false;
                            }
                        } else {
                            curOut++;
                            if (curOut > maxOut) {
                                maxOut = curOut;
                            }
                        }
                        break;
                }
            }
            out.println(maxOut + " " + inWords);
        }
        out.flush();
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;
        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }
        boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                return false;
            }
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
